import React, { useState, useEffect, useRef } from 'react';
import { MapContainer, TileLayer, Marker,Polyline, Popup, useMapEvents } from 'react-leaflet';
import L from 'leaflet';
import VehicleIcon from './VehicleIcon';
import StationIcon from './StationIcon';

const MapClickHandler = ({ onMapClick }) => {
  useMapEvents({
    click: (e) => {
      if (e && e.latlng) {
        const { lat, lng } = e.latlng;
        onMapClick({ lat, lng });
      } else {
        console.error("LatLng is undefined", e);
      }
    },
  });
  return null;
};

const getOffset = (index) => {
  const offset = 0.0002; // Adjust this value for better spacing
  return {
    lat: (index % 10) * offset,
    lng: Math.floor(index / 10) * offset
  };
};

const interpolatePosition = (start, end, fraction) => {
  return {
    lat: start.lat + (end.lat - start.lat) * fraction,
    lng: start.lng + (end.lng - start.lng) * fraction
  };
};

const animateVehicle = (start, end, duration, updatePosition) => {
  const startTime = performance.now();

  function step(currentTime) {
    const elapsed = currentTime - startTime;
    const fraction = Math.min(elapsed / duration, 1);
    const position = interpolatePosition(start, end, fraction);

    updatePosition(position);

    if (fraction < 1) {
      requestAnimationFrame(step);
    }
  }

  requestAnimationFrame(step);
};

const getVehicleColor = (id) => {
  const colors = [
    'blue',    // 0
    'red',     // 1
    'green',   // 2
    'purple',  // 3
    'orange',  // 4
    'cyan',    // 5
    'magenta', // 6
    'brown',   // 7
    'pink',    // 8
    'yellow'   // 9
  ];
  return colors[id % colors.length]; // Associe une couleur basée sur l'ID du véhicule
};

const MapComponent = React.memo(({ vehicles, stations, onMapClick }) => {
  const [vehicleTrails, setVehicleTrails] = useState([]);
  let color = "blue";
  useEffect(() => {
    // Fonction pour calculer les trajets des véhicules
    const calculateTrails = () => {
      return vehicles.map((vehicle) => {
        const end = vehicle.location; // Point d'arrivée
        const start = vehicle.previousLocation;
        console.log("end loca ", end);
        console.log("start loca", start);
        // Vérifiez si les coordonnées sont définies
        if (!start || !end || !start.lat || !start.lng || !end.lat || !end.lng) {
          console.error('Start or end location is undefined for vehicle', vehicle.id);
          return [];
        }

        color = getVehicleColor(vehicle.id);
        // Retournez le trajet sous forme de tableau
        return {
          color: color,
          trail: [
            [start.lat, start.lng],
            [end.lat, end.lng]
          ]
        };
      }).filter(trail => trail.length > 0); // Filtrer les trajets vides
    };

    // Calculer les trajets lorsque les véhicules ou le point de départ changent
    const newTrails = calculateTrails();
    setVehicleTrails(prevTrails => {
      // Ajoutez uniquement les nouveaux trajets
      return [...prevTrails, ...newTrails];
    });
  }, [vehicles]);

  // Styles pour les lignes
  const lineStyle = (color) => ({
    color: color,
    weight: 5,
    opacity: 0.7
  });

  return (
    <MapContainer center={[-37.814, 144.96332]} zoom={13} style={{ height: '100%', width: '100%' }}>
      <TileLayer
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        attribution="&copy; <a href='https://www.openstreetmap.org/copyright'>OpenStreetMap</a> contributors"
      />
      <MapClickHandler onMapClick={onMapClick} />
      {vehicles.map((vehicle, index) => {
        const offset = getOffset(index);
        const position = [vehicle.location.lat + offset.lat, vehicle.location.lng + offset.lng];
        return (
          <Marker key={vehicle.id} position={position} icon={VehicleIcon}>
            <Popup>
              <div>
                <h3>{vehicle.name}</h3>
                <p>Capacity: {vehicle.battery_capacity}</p>
                <p>Battery: {vehicle.battery}</p>
                <p>Consumption: {vehicle.consumption}</p>
              </div>
            </Popup>
          </Marker>
        );
      })}
      {stations.map((station, index) => {
        const offset = getOffset(index + vehicles.length);
        const position = [station.location.lat + offset.lat, station.location.lng + offset.lng];
        return (
          <Marker key={station.id} position={position} icon={StationIcon}>
            <Popup>
              <div>
                <h3>{station.name}</h3>
                <p>Price per kwh: {station.price_per_kwh}</p>
                <p>Charging speed: {station.charging_speed}</p>
                <p>Buy price per kwh: {station.buy_price_per_kwh}</p>
                <p>Discharging speed: {station.discharging_speed}</p>
              </div>
            </Popup>
          </Marker>
        );
      })}
      {vehicleTrails.map((color, trail, index) => (
        trail.length > 1 && (
          <Polyline key={index} positions={trail} pathOptions={lineStyle(color)} />
        )
      ))}
    </MapContainer>
  );
});

export default MapComponent;
